starter.template:
// Read a knob on A0 and dim an LED on D5
const int KNOB = A0;      // potentiometer wiper, 0-3.3 V
const int LED_PIN = D5;   // D5 is GPIO14: PWM-capable and quiet at boot

void setup() {
  Serial.begin(115200);
  analogWriteRange(255);  // 0-255 is already the default in core 3.x
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int raw = analogRead(KNOB);             // 0-1023 for 0-3.2 V on the A0 pin
  int duty = map(raw, 0, 1023, 0, 255);   // scale 10-bit input to 8-bit duty
  analogWrite(LED_PIN, duty);
  Serial.print("knob=");
  Serial.print(raw);
  Serial.print(" duty=");
  Serial.println(duty);
  delay({{p:every}});
}

